# ============================================================================ # main.py - VixSrc + CB01 Stremio Addon (FIXED) # ============================================================================ import json import logging import re import os from typing import Dict, Optional, Any, Tuple, List from urllib.parse import urljoin, quote from datetime import datetime from curl_cffi.requests import AsyncSession from bs4 import BeautifulSoup, SoupStrainer from fake_headers import Headers from dotenv import load_dotenv from fastapi import FastAPI, HTTPException, Request from fastapi.responses import JSONResponse from fastapi.middleware.cors import CORSMiddleware from slowapi import Limiter from slowapi.util import get_remote_address from slowapi.middleware import SlowAPIMiddleware load_dotenv() # ============================================================================ # CONFIGURAZIONE # ============================================================================ ADDON_NAME = "UFO addon" ADDON_LOGO = "https://static.vecteezy.com/system/resources/thumbnails/050/270/611/small/ufo-logo-design-no-background-perfect-for-print-on-demand-t-shirt-design-png.png" CONFIG = { "Siti": { "StreamingCommunity": { "url": "https://vixsrc.to", "enabled": "1" }, "CB01": { "url": "https://cb01.uno", "enabled": "1" } } } # LOGGING logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s") logger = logging.getLogger(__name__) # ============================================================================ # UTILITIES & TMDB HELPERS # ============================================================================ User_Agent = "Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:127.0) Gecko/20100101 Firefox/127.0" TMDB_API_KEY = os.getenv('TMDB_KEY', '536b1c46da222eb34b69d168f092b495') def clean_id(id_str: str) -> str: return id_str.split(':')[0] if ':' in id_str else id_str async def get_tmdb_id_from_imdb(imdb_id: str, client: AsyncSession) -> Optional[int]: try: response = await client.get( f"https://api.themoviedb.org/3/find/{imdb_id}", params={"external_source": "imdb_id", "api_key": TMDB_API_KEY, "language": "it"}, timeout=10 ) if response.status_code == 200: data = response.json() if data.get('movie_results'): return data['movie_results'][0].get('id') if data.get('tv_results'): return data['tv_results'][0].get('id') return None except Exception as e: logger.error(f"❌ Error converting IMDb ID: {e}") return None async def get_media_title(client: AsyncSession, tmdb_id: int, is_series: bool, season: str = None, episode: str = None) -> str: """Recupera il titolo formattato da TMDB.""" try: language = "it-IT" params = {"api_key": TMDB_API_KEY, "language": language} if not is_series: url = f"https://api.themoviedb.org/3/movie/{tmdb_id}" response = await client.get(url, params=params, timeout=5) if response.status_code == 200: data = response.json() return data.get("title", f"Film {tmdb_id}") return f"Film {tmdb_id}" else: ep_url = f"https://api.themoviedb.org/3/tv/{tmdb_id}/season/{season}/episode/{episode}" ep_resp = await client.get(ep_url, params=params, timeout=5) if ep_resp.status_code == 200: ep_data = ep_resp.json() return ep_data.get('name', f"Episodio {episode}") return f"Episodio {episode}" except Exception as e: logger.error(f"❌ Errore recupero titolo TMDB: {e}") if is_series: return f"Episodio {episode}" return "Film" async def get_tmdb_data(client: AsyncSession, tmdb_id: int, is_series: bool) -> Dict: """Recupera dati TMDB (titolo, anno, poster)""" try: endpoint = "tv" if is_series else "movie" response = await client.get( f"https://api.themoviedb.org/3/{endpoint}/{tmdb_id}", params={"api_key": TMDB_API_KEY, "language": "it"}, timeout=5 ) if response.status_code == 200: data = response.json() return { "title": data.get('name' if is_series else 'title', ''), "year": (data.get('first_air_date') or data.get('release_date') or '').split('-')[0], "poster": data.get('poster_path', ''), "overview": data.get('overview', '') } except Exception as e: logger.warning(f"⚠️ Error fetching TMDB data: {e}") return {"title": "", "year": "", "poster": "", "overview": ""} # ============================================================================ # EXTRACTORS # ============================================================================ class StreamingCommunityExtractor: def __init__(self): self.domain = CONFIG['Siti']['StreamingCommunity']['url'] self.random_headers = Headers() async def extract_vixcloud_url(self, link: str, client: AsyncSession) -> List[Dict]: """Estrae l'URL della Master Playlist da VixSrc.""" try: logger.info(f"🔍 [VixSrc] Fetching: {link}") headers = self.random_headers.generate() headers['Referer'] = f"{self.domain}/" headers['User-Agent'] = User_Agent response = await client.get(link, headers=headers, timeout=15) if response.status_code != 200: logger.warning(f"⚠️ [VixSrc] Status {response.status_code}") return [] soup = BeautifulSoup(response.text, "lxml") scripts = soup.find_all("script") video_data = None for script in scripts: if script.string and "token" in script.string and "expires" in script.string: video_data = script.string break if not video_data: logger.warning(f"⚠️ [VixSrc] No video data found") return [] token_match = re.search(r"'token':\s*'(\w+)'", video_data) expires_match = re.search(r"'expires':\s*'(\d+)'", video_data) url_match = re.search(r"url:\s*'([^']+)'", video_data) if not all([token_match, expires_match, url_match]): logger.warning(f"⚠️ [VixSrc] Missing token/expires/url") return [] token = token_match.group(1) expires = expires_match.group(1) server_url = url_match.group(1) separator = "&" if "?" in server_url else "?" final_url = f"{server_url}{separator}token={token}&expires={expires}" if "?b=1" in server_url and "b=1" not in final_url: final_url += "&b=1" if "window.canPlayFHD = true" in video_data: final_url += "&h=1" if ".m3u8" not in final_url: if "?" in final_url: base, params = final_url.split("?", 1) if not base.endswith(".m3u8"): final_url = f"{base}.m3u8?{params}" else: final_url += ".m3u8" detected_quality = "Auto" max_height = 0 try: m3u8_res = await client.get(final_url, headers=headers, timeout=6) if m3u8_res.status_code == 200: lines = m3u8_res.text.splitlines() for line in lines: if "RESOLUTION=" in line: res_match = re.search(r'RESOLUTION=(\d+)x(\d+)', line) if res_match: height = int(res_match.group(2)) if height > max_height: max_height = height if max_height > 0: detected_quality = f"{max_height}p" except Exception as e: logger.warning(f"⚠️ [VixSrc] Could not parse m3u8 metadata: {e}") if max_height == 0 and "window.canPlayFHD = true" in video_data: detected_quality = "1080p" elif max_height == 0: detected_quality = "720p" logger.info(f"✅ [VixSrc] URL generated. Quality: {detected_quality}") return [{ "quality": detected_quality, "url": final_url, "height": max_height }] except Exception as e: logger.error(f"❌ [VixSrc] Extractor Error: {e}") return [] async def get_streams(self, id: str, client: AsyncSession) -> Dict: streams = {'streams': []} try: is_series = False season = None episode = None content_id = clean_id(id) if ':' in id: parts = id.split(':') content_id = parts[0] if len(parts) >= 3: season, episode = parts[1], parts[2] is_series = True tmdb_id = None if content_id.startswith('tt'): tmdb_id = await get_tmdb_id_from_imdb(content_id, client) if not tmdb_id: return streams else: try: tmdb_id = int(content_id) except ValueError: return streams media_title = await get_media_title(client, tmdb_id, is_series, season, episode) url = f'{self.domain}/tv/{tmdb_id}/{season}/{episode}/' if is_series else f'{self.domain}/movie/{tmdb_id}/' results = await self.extract_vixcloud_url(url, client) for res in results: streams['streams'].append({ "name": f"🛸 VixSrc {res['quality']}", "title": media_title, "url": res['url'], "behaviorHints": { "proxyHeaders": {"request": {"user-agent": User_Agent}}, "notWebReady": True, "bingeGroup": "vixsrc" } }) except Exception as e: logger.error(f"❌ [VixSrc] Stream Error: {e}") return streams class CB01Extractor: """CB01 Extractor - Direct m3u8 extraction from player""" def __init__(self): self.domain = CONFIG['Siti']['CB01']['url'] self.random_headers = Headers() async def search_content(self, title: str, year: str, is_series: bool, season: str = None, client: AsyncSession = None) -> Optional[str]: """Ricerca contenuto su CB01 e restituisce URL player page""" try: # Pulizia titolo per ricerca title_clean = title.replace(" ", "+").lower() for char in ['ò', 'è', 'à', 'ù', 'é']: title_clean = title_clean.replace(char, char[0]) headers = self.random_headers.generate() headers['Referer'] = f'{self.domain}/' headers['User-Agent'] = User_Agent if is_series: search_url = f'{self.domain}/serietv/?s={title_clean}' logger.info(f"🔍 [CB01] Ricerca serie: {title} ({year})") else: search_url = f'{self.domain}/?s={title_clean}' logger.info(f"🔍 [CB01] Ricerca film: {title} ({year})") response = await client.get(search_url, headers=headers, timeout=10) if response.status_code != 200: logger.warning(f"⚠️ [CB01] Status {response.status_code}") return None soup = BeautifulSoup(response.text, 'lxml') # Cerca nei risultati di ricerca articles = soup.find_all('article', class_='item') for article in articles: try: link_tag = article.find('a', href=True) if not link_tag: continue href = link_tag.get('href') if not href: continue # Estrai anno dall'URL (es: /film/titolo-2024/) url_parts = href.rstrip('/').split('/') if len(url_parts) > 0: last_part = url_parts[-1] year_match = re.search(r'(\d{4})', last_part) if year_match: found_year = year_match.group(1) # Verifica corrispondenza anno (con tolleranza ±1) if abs(int(found_year) - int(year)) <= 1: logger.info(f"✅ [CB01] Trovato: {href}") return href except Exception as e: logger.debug(f"⚠️ [CB01] Errore parsing article: {e}") continue logger.warning(f"⚠️ [CB01] Nessun risultato per: {title} ({year})") return None except Exception as e: logger.error(f"❌ [CB01] Errore ricerca: {e}") return None async def extract_m3u8_from_player(self, player_url: str, client: AsyncSession) -> Optional[str]: """Estrae URL m3u8 dalla pagina player CB01""" try: logger.info(f"🔍 [CB01] Estraendo stream da: {player_url}") headers = self.random_headers.generate() headers['Referer'] = player_url headers['User-Agent'] = User_Agent response = await client.get(player_url, headers=headers, timeout=10) if response.status_code != 200: logger.warning(f"⚠️ [CB01] Status {response.status_code}") return None soup = BeautifulSoup(response.text, 'lxml') # Cerca script con iframe src o URL m3u8 scripts = soup.find_all('script') m3u8_url = None for script in scripts: if script.string: # Cerca iframe src iframe_match = re.search(r']+src=["\']([^"\']+)["\']', script.string) if iframe_match: iframe_url = iframe_match.group(1) logger.info(f"🔗 [CB01] Found iframe: {iframe_url}") # Se è URL esterno (vixcloud, etc), estrai m3u8 if 'vixcloud' in iframe_url.lower() or 'streaming' in iframe_url.lower(): m3u8_match = re.search(r'(https?://[^\s]+\.m3u8[^\s]*)', iframe_url) if m3u8_match: m3u8_url = m3u8_match.group(1) break # Altrimenti cerca URL m3u8 diretto m3u8_direct = re.search(r'(https?://[^\s"\']+\.m3u8[^\s"\']*)', script.string) if m3u8_direct: m3u8_url = m3u8_direct.group(1) break if m3u8_url: logger.info(f"✅ [CB01] m3u8 estratto: {m3u8_url}") return m3u8_url # Fallback: ritorna page URL se no m3u8 trovato (Stremio lo aprirà in browser) logger.warning(f"⚠️ [CB01] No m3u8 found, usando fallback page") return player_url except Exception as e: logger.error(f"❌ [CB01] Errore estrazione: {e}") return None async def get_streams(self, id: str, client: AsyncSession) -> Dict: """Estrae stream da CB01""" streams = {'streams': []} try: is_series = False season = None episode = None content_id = clean_id(id) if ':' in id: parts = id.split(':') content_id = parts[0] if len(parts) >= 3: season, episode = parts[1], parts[2] is_series = True tmdb_id = None if content_id.startswith('tt'): tmdb_id = await get_tmdb_id_from_imdb(content_id, client) if not tmdb_id: return streams else: try: tmdb_id = int(content_id) except ValueError: return streams media_title = await get_media_title(client, tmdb_id, is_series, season, episode) tmdb_data = await get_tmdb_data(client, tmdb_id, is_series) if not tmdb_data['title'] or not tmdb_data['year']: logger.warning(f"⚠️ [CB01] Dati TMDB incompleti") return streams # Ricerca su CB01 player_url = await self.search_content( tmdb_data['title'], tmdb_data['year'], is_series, season, client ) if not player_url: return streams # Estrai m3u8 dalla pagina player stream_url = await self.extract_m3u8_from_player(player_url, client) if stream_url: # Determina qualità basata su dimensione URL o meta quality = "720p" is_m3u8 = ".m3u8" in stream_url.lower() streams['streams'].append({ "name": f"📺 CB01 {quality}", "title": media_title, "url": stream_url, "behaviorHints": { "proxyHeaders": {"request": {"user-agent": User_Agent}}, "notWebReady": not is_m3u8, # Se è m3u8, è webReady "bingeGroup": "cb01" } }) logger.info(f"✅ [CB01] Stream aggiunto per {media_title}") except Exception as e: logger.error(f"❌ [CB01] Stream Error: {e}") return streams # ============================================================================ # FASTAPI SETUP # ============================================================================ app = FastAPI(title=f"{ADDON_NAME} Addon") app.add_middleware( CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"], ) limiter = Limiter(key_func=get_remote_address) app.state.limiter = limiter app.add_middleware(SlowAPIMiddleware) vixsrc_extractor = StreamingCommunityExtractor() cb01_extractor = CB01Extractor() def respond_with(data: Any) -> JSONResponse: resp = JSONResponse(content=data) resp.headers["Access-Control-Allow-Origin"] = "*" resp.headers["Access-Control-Allow-Headers"] = "*" return resp # ============================================================================ # ROUTES # ============================================================================ @app.get("/") async def root(request: Request): base_url = str(request.base_url).rstrip("/") return respond_with({ "status": "online", "addon": ADDON_NAME, "manifest": f"{base_url}/U0MQ/manifest.json" }) @app.get("/U0MQ/manifest.json") async def manifest(): config = { "id": "org.stremio.mammamia.ufo", "version": "1.5.0", "name": ADDON_NAME, "description": "VixSrc + CB01 Streams via Vercel", "logo": ADDON_LOGO, "resources": ["stream"], "types": ["movie", "series"], "catalogs": [], "behaviorHints": {"configurable": False} } return respond_with(config) @app.get("/U0MQ/stream/{type}/{id}.json") @limiter.limit("10/second") async def streams(request: Request, type: str, id: str): try: if type not in ["movie", "series"]: raise HTTPException(status_code=404) async with AsyncSession() as client: # Priorità: VixSrc prima, CB01 come fallback streams_data = await vixsrc_extractor.get_streams(id, client) # Se VixSrc non ha trovato stream, prova CB01 if not streams_data.get('streams'): logger.info(f"ℹ️ VixSrc nessuno stream, provo CB01...") streams_data = await cb01_extractor.get_streams(id, client) else: # Se VixSrc ha trovato stream, aggiungi CB01 come fallback cb01_streams = await cb01_extractor.get_streams(id, client) if cb01_streams.get('streams'): streams_data['streams'].extend(cb01_streams['streams']) if not streams_data: streams_data = {"streams": []} return respond_with(streams_data) except Exception as e: logger.error(f"❌ Stream endpoint error: {e}") return respond_with({"streams": []}) @app.get("/U0MQ/meta/{type}/{id}.json") async def meta(type: str, id: str): return respond_with({ "meta": { "id": id, "type": type, "name": ADDON_NAME, "poster": ADDON_LOGO } }) @app.get("/U0MQ/catalog/{type}/{id}.json") async def catalog(type: str, id: str): return respond_with({"metas": []}) # ============================================================================ # RUN SERVER # ============================================================================ if __name__ == "__main__": import uvicorn uvicorn.run(app, host="0.0.0.0", port=8000, log_level="info")
